import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

async function getAveragePrice(asset: string, currency: string): Promise<number> {
  const avgPrice = await prisma.priceHistory.aggregate({
    _avg: {
      price: true,
    },
    where: {
